// Progress DB migrations, generated by `dart run drift_dev make-migrations`
// and filled in: every schema step is validated against the dumped schemas
// (drift_schemas/progress/), v1 -> v2 and v2 -> v3 keep every existing row.
// ignore_for_file: unused_local_variable, unused_import
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:tosk/core/core.dart';
import 'package:tosk/data/progress/bookmarks.dart';
import 'package:tosk/data/progress/feedback_store.dart';
import 'package:tosk/data/progress/progress_db.dart';
import 'package:flutter_test/flutter_test.dart';

import 'generated/schema.dart';

import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;
import 'generated/schema_v3.dart' as v3;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // Every possible schema update with an empty database.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = ProgressDb(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('migration from v1 to v2 keeps the review log, states, mistakes and settings', () async {
    const log = [
      v1.ReviewLogData(
        id: 'e1',
        facetId: 'it:pane#rec',
        at: 1760000000000,
        rating: 3,
        exerciseType: 'multiple_choice',
        inputMode: 'tap',
        responseMs: 1200,
        correct: 1,
        answer: 'bread',
        sessionId: 's1',
        mode: 'lesson',
      ),
      v1.ReviewLogData(
        id: 'e2',
        facetId: 'it:mangiare#form:presente',
        at: 1760000005000,
        rating: 1,
        exerciseType: 'conj_pick',
        inputMode: 'tap',
        responseMs: 3400,
        correct: 0,
      ),
    ];
    const states = [
      v1.FacetStateData(
        facetId: 'it:pane#rec',
        stability: 2.3,
        difficulty: 5.1,
        due: 1760100000000,
        lastReview: 1760000000000,
        reps: 1,
        lapses: 0,
        phase: 'learning',
        step: 1,
      ),
    ];
    const mistakes = [
      v1.MistakesData(
        id: 'e2',
        facetId: 'it:mangiare#form:presente',
        at: 1760000005000,
        exerciseType: 'conj_pick',
        prompt: 'mangiare (noi): mang___',
        expected: 'mangiamo',
        given: 'mangiate',
        skillId: 'present_are',
        note: '# -are',
      ),
    ];
    const settings = [v1.SettingsData(key: 'ui.source_lang', value: 'nl')];

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: ProgressDb.new,
      createItems: (batch, oldDb) {
        batch.insertAll(oldDb.reviewLog, log);
        batch.insertAll(oldDb.facetState, states);
        batch.insertAll(oldDb.mistakes, mistakes);
        batch.insertAll(oldDb.settings, settings);
      },
      validateItems: (newDb) async {
        final newLog = await newDb.select(newDb.reviewLog).get();
        expect(newLog.map((r) => r.toJson()), log.map((r) => r.toJson()));
        expect(
          (await newDb.select(newDb.facetState).get()).map((r) => r.toJson()),
          states.map((r) => r.toJson()),
        );
        expect(
          (await newDb.select(newDb.mistakes).get()).map((r) => r.toJson()),
          mistakes.map((r) => r.toJson()),
        );
        expect(
          (await newDb.select(newDb.settings).get()).map((r) => r.toJson()),
          settings.map((r) => r.toJson()),
        );
        expect(await newDb.select(newDb.aiExplanations).get(), isEmpty);
        expect(await newDb.select(newDb.flags).get(), isEmpty);
      },
    );
  });

  test('a migrated v1 database stores explanations and flags', () async {
    final schema = await verifier.schemaAt(1);
    final db = ProgressDb(schema.newConnection());
    await verifier.migrateAndValidate(db, 2);
    final store = DriftFeedbackStore(db);
    await store.saveExplanation(
      CachedExplanation(fingerprint: 'abc', given: 'x', lang: 'en', text: 'Because.', createdAt: DateTime.utc(2026)),
    );
    expect((await store.explanation('abc', 'x', 'en'))?.text, 'Because.');
    await db.close();
  });

  test('migration from v2 to v3 keeps every row and adds an empty bookmarks table', () async {
    const log = [
      v2.ReviewLogData(
        id: 'e1',
        facetId: 'it:pane#rec',
        at: 1760000000000,
        rating: 3,
        exerciseType: 'cloze',
        inputMode: 'tap',
        responseMs: 1500,
        correct: 1,
        sessionId: 's1',
        mode: 'lesson',
      ),
    ];
    const settings = [v2.SettingsData(key: 'course.active', value: 'it')];
    const flags = [
      v2.FlagsData(
        id: 'f1',
        createdAt: 1760000001000,
        courseId: 'it',
        facetId: 'it:pane#rec',
        exerciseType: 'cloze',
        exerciseJson: '{}',
        given: 'a',
        expected: 'b',
        correct: 0,
        reason: 'other',
        comment: '',
      ),
    ];
    const explanations = [
      v2.AiExplanationsData(fingerprint: 'fp', given: 'a', lang: 'en', body: 'Because.', createdAt: 1760000002000),
    ];
    await verifier.testWithDataIntegrity(
      oldVersion: 2,
      newVersion: 3,
      createOld: v2.DatabaseAtV2.new,
      createNew: v3.DatabaseAtV3.new,
      openTestedDatabase: ProgressDb.new,
      createItems: (batch, oldDb) {
        batch.insertAll(oldDb.reviewLog, log);
        batch.insertAll(oldDb.settings, settings);
        batch.insertAll(oldDb.flags, flags);
        batch.insertAll(oldDb.aiExplanations, explanations);
      },
      validateItems: (newDb) async {
        expect((await newDb.select(newDb.reviewLog).get()).map((r) => r.toJson()), log.map((r) => r.toJson()));
        expect((await newDb.select(newDb.settings).get()).map((r) => r.toJson()), settings.map((r) => r.toJson()));
        expect((await newDb.select(newDb.flags).get()).map((r) => r.toJson()), flags.map((r) => r.toJson()));
        expect(
          (await newDb.select(newDb.aiExplanations).get()).map((r) => r.toJson()),
          explanations.map((r) => r.toJson()),
        );
        expect(await newDb.select(newDb.bookmarks).get(), isEmpty);
      },
    );
  });

  test('a migrated v2 database stores and reads bookmarks', () async {
    final schema = await verifier.schemaAt(2);
    final db = ProgressDb(schema.newConnection());
    await verifier.migrateAndValidate(db, 3);
    final repo = DriftBookmarkRepo(db);
    final at = DateTime.utc(2026, 10, 20, 9);
    await repo.put('it', [
      Bookmark(kind: BookmarkKind.word, id: 'it:pane', at: at, label: 'il pane', detail: 'bread'),
      Bookmark(kind: BookmarkKind.sentence, id: 's:1', at: at, removed: true),
    ]);
    final set = await repo.load('it');
    expect(set.contains(BookmarkKind.word, 'it:pane'), isTrue);
    expect(set.contains(BookmarkKind.sentence, 's:1'), isFalse);
    expect(set.all, hasLength(2));
    expect(await repo.load('nl'), isA<BookmarkSet>().having((s) => s.all, 'all', isEmpty));
    await db.close();
  });
}
